/**
 * Report insights: the top-level findings, each tied to the question (theme) it
 * came from and the Polis statements that support it.
 *
 * Data lives in insights.json, generated by `npm run import:insights`
 * from the report export in references/. Don't edit the JSON by hand.
 */
import data from './insights.json';
import { allStatements } from './polis';
import { participant, type Participant } from './participants';

export type Direction = 'agree' | 'divided' | 'mixed';
export type VoteTally = { total: number; agree: number; disagree: number; pass: number; agreePct: number };

export type InsightStatement = {
  /** Polis comment id (matches comment-id in polis/comments.csv). */
  id: number;
  source: 'poll' | 'session' | 'unknown';
  text: string;
  votes: VoteTally & { groups: Record<string, VoteTally> };
};

export type Insight = {
  id: string;
  claim: string;
  direction: Direction;
  /** Id of the question/topic this insight belongs to (see topics.ts). */
  question: string;
  theme: string;
  statements: InsightStatement[];
};

/** Opinion groups the report's vote breakdowns use, e.g. ['A', 'B', 'C']. */
export const insightGroups: string[] = data.groups;

export const insights = data.insights as Insight[];

export const insightsFor = (questionId: string) => insights.filter((i) => i.question === questionId);

const authors = new Map(allStatements.map((s) => [s.id, s.authorId]));

/** Who wrote a supporting statement, for consistent avatars (falls back to Host). */
export const authorOf = (s: InsightStatement): Participant => participant(authors.get(s.id) ?? 0);
